"""Calculates gyroscopic precession torque generated by rotating propeller assemblies."""

def calculate_gyroscopic_torque_nm(prop_inertia_kg_m2: float, prop_rpm: float, yaw_rate_rad_s: float) -> float:
    """Torque equation: Tau = I * omega * Omega_yaw."""
    omega_prop = prop_rpm * (2.0 * 3.14159265 / 60.0)
    torque = prop_inertia_kg_m2 * omega_prop * yaw_rate_rad_s
    return torque
